using U=unsigned __int128;using Clock=std::chrono::steady_clock;
template<int N>struct Mask{std::array<uint64_t,N>w{};bool operator==(const Mask&o)const{return w==o.w;}bool empty()const{for(auto x:w)if(x)return false;return true;}int size()const{int n=0;for(auto x:w)n+=__builtin_popcountll(x);return n;}bool has(int j)const{return(w[j/64]>>(j%64))&1;}void add(int j){w[j/64]|=1ull<<(j%64);}};
template<int N>struct Hash{size_t operator()(const Mask<N>&m)const{uint64_t h=0x9e3779b97f4a7c15ull;for(auto x:m.w){x^=x>>30;x*=0xbf58476d1ce4e5b9ull;x^=x>>27;x*=0x94d049bb133111ebull;x^=x>>31;h^=x+0x9e3779b97f4a7c15ull+(h<<6)+(h>>2);}return h;}};
template<int N>Mask<N>meet(const Mask<N>&a,const Mask<N>&b){Mask<N>z;for(int i=0;i<N;i++)z.w[i]=a.w[i]&b.w[i];return z;}
template<int N>bool subset(const Mask<N>&a,const Mask<N>&b){for(int i=0;i<N;i++)if(a.w[i]&~b.w[i])return false;return true;}
using M6=Mask<12>;using M7=Mask<79>;
struct HU{size_t operator()(U x)const{return(uint64_t)x*0x9e3779b97f4a7c15ull^((uint64_t)(x>>64))*0xbf58476d1ce4e5b9ull;}};
uint64_t rd64(std::ifstream&f){uint64_t x;f.read((char*)&x,8);return x;}uint32_t rd32(std::ifstream&f){uint32_t x;f.read((char*)&x,4);return x;}U rdU(std::ifstream&f){U l=rd64(f),h=rd64(f);return l|(h<<64);}
void put16(std::string&s,int x){uint16_t z=x;s.push_back(z&255);s.push_back(z>>8);}int get16(const std::string&s,size_t&i){uint16_t z=(uint8_t)s[i]|((uint16_t)(uint8_t)s[i+1]<<8);i+=2;return(int16_t)z;}
struct I6{uint32_t first,last,left,right,sw[5],old;};struct I7{uint32_t first,last,left,right;};std::vector<I6>i6;std::vector<I7>i7;std::unordered_map<U,int,HU>types;std::unordered_map<std::string,int>exceptions;
struct Six{int M,A,rb,rt,psi;std::vector<std::pair<int,int>>flow;};std::unordered_map<M6,Six,Hash<12>>cache;
std::vector<std::pair<int,int>>merge(std::vector<std::pair<int,int>>x){std::sort(x.begin(),x.end());std::vector<std::pair<int,int>>r;for(auto p:x){if(!r.empty()&&r.back().first==p.first)r.back().second+=p.second;else r.push_back(p);}r.erase(std::remove_if(r.begin(),r.end(),[](auto p){return p.second==0;}),r.end());return r;}
Six evaluate6(const M6&d){auto it=cache.find(d);if(it!=cache.end())return it->second;int M=d.size(),A=0,C=0,rb=0,rt=0;U ends[6]={},starts[6]={};
 for(int wi=0;wi<12;wi++){uint64_t word=d.w[wi];while(word){int b=__builtin_ctzll(word);word&=word-1;int q=64*wi+b;auto&I=i6[q];ends[I.last]|=U(1)<<I.left;starts[I.first]|=U(1)<<I.right;bool e[5];for(int j=0;j<5;j++){e[j]=d.has(I.sw[j]);A+=e[j];}C+=(e[0]&&e[1])-(!e[0]);if(!e[2]&&(!e[1]||!d.has(i6[I.sw[1]].sw[2]))&&(!e[3]||!d.has(i6[I.sw[3]].sw[2])))C++;if(e[1]&&e[2]){int a=I.sw[1],b=I.sw[2];if(!d.has(i6[a].sw[2])&&!d.has(i6[b].sw[1])&&!(d.has(i6[a].sw[3])&&d.has(i6[i6[a].sw[3]].sw[2]))&&!(d.has(i6[b].sw[0])&&d.has(i6[i6[b].sw[0]].sw[1])))C++;}}}
 std::vector<std::pair<int,int>>f;for(int j=0;j<6;j++){if(ends[j]){auto k=types.find(ends[j]);if(k==types.end())throw std::runtime_error("unknown bottom5");int c=k->second,n=__builtin_popcountll((uint64_t)ends[j])+__builtin_popcountll((uint64_t)(ends[j]>>64));f.push_back({c,n});rb+=c==866;}if(starts[j]){auto k=types.find(starts[j]);if(k==types.end())throw std::runtime_error("unknown top5");int c=k->second,n=__builtin_popcountll((uint64_t)starts[j])+__builtin_popcountll((uint64_t)(starts[j]>>64));f.push_back({c,-n});rt+=c==41;}}
 f=merge(f);std::string key;for(int x:{M,A,C,rb,rt})put16(key,x);for(auto p:f){put16(key,p.first);put16(key,p.second);}auto e=exceptions.find(key);Six s{M,A,rb,rt,e==exceptions.end()?-1:e->second,f};if(cache.size()<500000)cache.emplace(d,s);return s;
}
std::unordered_map<std::string,M7>rows;
void evaluate7(const M7&d){M6 ends[7],starts[7];int M=d.size(),A=0,flux=0;for(int wi=0;wi<79;wi++){uint64_t w=d.w[wi];while(w){int b=__builtin_ctzll(w);w&=w-1;int q=64*wi+b;auto&I=i7[q];ends[I.last].add(I.left);starts[I.first].add(I.right);}}std::vector<std::pair<int,int>>ff,pp;
 for(int j=0;j<7;j++)for(int side:{1,-1}){auto &m=side==1?ends[j]:starts[j];if(m.empty())continue;Six s=evaluate6(m);A+=s.A;for(auto p:s.flow)ff.push_back(p);if(s.psi>=0)pp.push_back({s.psi,side});else flux+=side*(s.rt-s.rb);}
 ff=merge(ff);pp=merge(pp);std::string key;put16(key,M);put16(key,A);put16(key,flux);put16(key,pp.size());for(auto p:pp){put16(key,p.first);put16(key,p.second);}for(auto p:ff){put16(key,p.first);put16(key,p.second);}rows.emplace(std::move(key),d);
}
int rank7(std::array<int,7>p){int r=0;for(int j=0;j<7;j++){int c=0;for(int k=j+1;k<7;k++)c+=p[j]>p[k];r=r*(7-j)+c;}return r;}
std::vector<int>rev7;M7 reverse7(const M7&d){M7 z;for(int wi=0;wi<79;wi++){uint64_t w=d.w[wi];while(w){int b=__builtin_ctzll(w);w&=w-1;z.add(rev7[64*wi+b]);}}return z;}
void save(){std::vector<std::string>kk;for(auto &p:rows)kk.push_back(p.first);std::sort(kk.begin(),kk.end());std::ofstream o("seven_complete.rows.txt"),w("seven_complete.witness.bin",std::ios::binary);uint64_t n=kk.size();w.write((char*)&n,8);for(auto &s:kk){size_t i=0;int M=get16(s,i),A=get16(s,i),flux=get16(s,i),np=get16(s,i);o<<M<<' '<<A<<' '<<flux;for(int j=0;j<np;j++){int k=get16(s,i),v=get16(s,i);o<<" p"<<k<<':'<<v;}while(i<s.size()){int k=get16(s,i),v=get16(s,i);o<<" f"<<k<<':'<<v;}o<<'\n';auto &d=rows.at(s);w.write((char*)d.w.data(),632);}}
int main(){auto start=Clock::now();std::ifstream a("full_window_input.bin",std::ios::binary),b("five_classes.bin",std::ios::binary),c("seven_window_input.bin",std::ios::binary),e("seven_exception_keys.bin",std::ios::binary),ss("seven_seeds.bin",std::ios::binary);int n6=rd64(a),nr=rd64(a);i6.resize(n6);for(auto &I:i6){I.first=rd32(a);I.last=rd32(a);I.left=rd32(a);I.right=rd32(a);for(auto&x:I.sw)x=rd32(a);I.old=rd32(a);}int br=rd64(b),bn=rd64(b);for(int j=0;j<br;j++)rdU(b);for(int j=0;j<bn;j++){U m=rdU(b);types[m]=rd32(b);}int n7=rd32(c);i7.resize(n7);for(auto&I:i7){I.first=rd32(c);I.last=rd32(c);I.left=rd32(c);I.right=rd32(c);}int ng=rd32(c);std::vector<std::vector<M7>>groups(ng);for(auto &g:groups){int no=rd32(c);g.resize(no);for(auto&m:g)c.read((char*)m.w.data(),632);}std::vector<std::vector<M7>> reordered;std::vector<int>oldidx,newidx;int gi=0;for(int aa=0;aa<7;aa++)for(int bb=aa+1;bb<7;bb++)for(int cc=bb+1;cc<7;cc++){(cc<6?oldidx:newidx).push_back(gi++);}for(int aa=0;aa<7;aa++)for(int bb=aa+1;bb<7;bb++){(bb<6?oldidx:newidx).push_back(gi++);}for(int x:oldidx)reordered.push_back(groups[x]);for(int x:newidx)reordered.push_back(groups[x]);groups.swap(reordered);int ne=rd32(e);for(int j=0;j<ne;j++){int id=rd32(e),len=rd32(e);std::string key(len,0);e.read(key.data(),len);exceptions[key]=id;}int nseed=rd32(ss);std::vector<M6>seeds(nseed);for(auto&m:seeds)ss.read((char*)m.w.data(),96);if(!a||!b||!c||!e||!ss)return 2;
 std::array<int,7>p{0,1,2,3,4,5,6};do{auto q=p;std::reverse(q.begin(),q.end());rev7.push_back(rank7(q));}while(std::next_permutation(p.begin(),p.end()));M7 full,bottom;for(int q=0;q<5040;q++){full.add(q);if(i7[q].last==6)bottom.add(q);}bool complete=true;uint64_t cases=0;std::ofstream log("seven_family_counts.txt");
 for(int z=0;z<nseed;z++){
  M7 req;for(int q=0;q<5040;q++)if(i7[q].last==6&&seeds[z].has(i7[q].left))req.add(q);std::vector<std::vector<M7>>allowed;for(auto &g:groups){std::vector<M7>v;for(auto&m:g)if(subset(req,m))v.push_back(m);if(v.empty())throw std::runtime_error("invalid required slice");allowed.push_back(v);}M7 base=full;bool change=true;while(change){change=false;for(auto&g:allowed){std::unordered_set<M7,Hash<79>>u;for(auto&m:g)u.insert(meet(base,m));if(u.size()==1){auto next=*u.begin();if(!(next==base)){base=next;change=true;}}}}
  std::vector<std::vector<M7>>gg;for(auto&g:allowed){std::unordered_set<M7,Hash<79>>u;for(auto&m:g)u.insert(meet(base,m));if(u.size()>1)gg.emplace_back(u.begin(),u.end());}std::vector<M7>suffix(gg.size()+1,full);for(int j=(int)gg.size()-1;j>=0;j--){M7 common=full;for(auto&m:gg[j])common=meet(common,m);suffix[j]=meet(suffix[j+1],common);}std::vector<M7>front{base};bool truncated=false;for(size_t g=0;g<gg.size();g++){std::unordered_set<M7,Hash<79>>next;next.reserve(front.size()*2);for(auto&d:front)for(auto&m:gg[g]){auto x=meet(d,m);if(subset(meet(meet(x,suffix[g+1]),bottom),req))next.insert(x);}std::cout<<"step "<<z<<":"<<g<<" front "<<next.size()<<std::endl;if(next.size()>500000){truncated=true;break;}front.assign(next.begin(),next.end());}
  if(truncated){complete=false;std::cout<<"TRUNCATED seed "<<z<<std::endl;break;}uint64_t count=0;for(auto&d:front)if(meet(d,bottom)==req){evaluate7(d);evaluate7(reverse7(d));count++;}cases+=count;double sec=std::chrono::duration<double>(Clock::now()-start).count();log<<z<<' '<<seeds[z].size()<<' '<<count<<'\n';log.flush();std::cout<<"seed "<<z+1<<'/'<<nseed<<" baseM "<<seeds[z].size()<<" front "<<front.size()<<" valid "<<count<<" rows "<<rows.size()<<" seconds "<<sec<<std::endl;
  if(sec>240){complete=false;break;}
 }
 save();std::ofstream j("seven_complete.result.json");j<<"{\"complete\":"<<(complete?"true":"false")<<",\"seeds\":"<<nseed<<",\"family_cases\":"<<cases<<",\"feature_rows\":"<<rows.size()<<",\"cached_six_slices\":"<<cache.size()<<",\"seconds\":"<<std::chrono::duration<double>(Clock::now()-start).count()<<"}\n";return 0;
}
